/**
 * Msg is the land registry's transaction surface.
 *
 * The shape to notice: no single signer can move a parcel. Proposing,
 * validating and attesting are three different signers by construction, and
 * completion is mechanical. That is the anti-bribery property, expressed as a
 * message set rather than as policy.
 */
export interface Msg {
  /** UpdateParams sets the quorum and challenge window. Governance only. */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /**
   * Admitting a registry office is a governance act. If an authority could
   * admit another authority, buying one office would buy the power to
   * manufacture the independent attestors the quorum depends on.
   */
  RegisterAuthority(request: MsgRegisterAuthority): Promise<MsgRegisterAuthorityResponse>;
  /** RegisterParcel records a parcel for the first time. */
  RegisterParcel(request: MsgRegisterParcel): Promise<MsgRegisterParcelResponse>;
  /** ProposeTransfer opens a transfer. Signed by the holder. */
  ProposeTransfer(request: MsgProposeTransfer): Promise<MsgProposeTransferResponse>;
  /** ValidateTransfer records the jurisdiction's own validation. */
  ValidateTransfer(request: MsgValidateTransfer): Promise<MsgValidateTransferResponse>;
  /** AttestTransfer adds one independent attestation toward quorum. */
  AttestTransfer(request: MsgAttestTransfer): Promise<MsgAttestTransferResponse>;
  /** Object halts a transfer and marks the parcel disputed. */
  Object(request: MsgObject): Promise<MsgObjectResponse>;
  /** CompleteTransfer applies a transfer that has met every condition. */
  CompleteTransfer(request: MsgCompleteTransfer): Promise<MsgCompleteTransferResponse>;
  /** RecordEncumbrance adds or releases a lien or right of way. */
  RecordEncumbrance(request: MsgRecordEncumbrance): Promise<MsgRecordEncumbranceResponse>;
  /** FreezeParcel stops all movement, or lifts a freeze. */
  FreezeParcel(request: MsgFreezeParcel): Promise<MsgFreezeParcelResponse>;
  /** AttachDeed adds a document to the chain of title. */
  AttachDeed(request: MsgAttachDeed): Promise<MsgAttachDeedResponse>;
  /** SetRestriction imposes or lifts a limit on what may be done with a parcel. */
  SetRestriction(request: MsgSetRestriction): Promise<MsgSetRestrictionResponse>;
  /**
   * AuthoriseFractionalisation is the registry's permission for a tokenisation
   * vehicle to be opened over a parcel. Without it, x/tokenisation refuses.
   */
  AuthoriseFractionalisation(request: MsgAuthoriseFractionalisation): Promise<MsgAuthoriseFractionalisationResponse>;
}

